CREATE POLICY "booking_docs admin upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'booking-documents' AND private.has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "booking_docs admin update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'booking-documents' AND private.has_role(auth.uid(), 'admin'::app_role));